-- Exact function-body checks in addition to migration ledger and permissions.
WITH checks(name,ok) AS (
 SELECT 'ledger',EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20261026000000' AND name='question_practice_adaptation_v2' AND cardinality(statements)=1 AND md5(statements[1])='354934137b8be264f4b1b2cf58d36b2e')
 UNION ALL SELECT 'question_practice_expected_seconds' AS name,coalesce((SELECT md5(prosrc)='86b03f6166861027f963df9712895e75' AND prosecdef=false AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_expected_seconds(public.question_difficulty)')),false) AS ok
 UNION ALL SELECT 'question_practice_target' AS name,coalesce((SELECT md5(prosrc)='89c8704956cbf6a85fafb47063e1f9af' AND prosecdef=false AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_target(bigint,bigint)')),false) AS ok
 UNION ALL SELECT 'question_practice_signals' AS name,coalesce((SELECT md5(prosrc)='a18312b9fe60c31fbdde267d9241e6ae' AND prosecdef=true AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_signals()')),false) AS ok
 UNION ALL SELECT 'question_practice_snapshot' AS name,coalesce((SELECT md5(prosrc)='1162f028c31bdeab0a9fdd0e77b48089' AND prosecdef=true AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.question_practice_snapshot(uuid)')),false) AS ok
 UNION ALL SELECT 'submit_question_practice_v2' AS name,coalesce((SELECT md5(prosrc)='d4088db3fa9026ae6dd0017bc05e6295' AND prosecdef=true AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.submit_question_practice_v2(uuid,uuid,uuid,integer,jsonb,boolean)')),false) AS ok
 UNION ALL SELECT 'submit_question_practice' AS name,coalesce((SELECT md5(prosrc)='8e0d09ff04da8cd43fe814c87a6db3ce' AND prosecdef=true AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.submit_question_practice(uuid,uuid,uuid,integer)')),false) AS ok
 UNION ALL SELECT 'start_question_practice' AS name,coalesce((SELECT md5(prosrc)='3c38ab52a179bc0485a2026f5675b620' AND prosecdef=true AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.start_question_practice(uuid,uuid)')),false) AS ok
 UNION ALL SELECT 'get_question_practice_analysis' AS name,coalesce((SELECT md5(prosrc)='7a7a1a1db46c9a4093555d13aabfd0e0' AND prosecdef=true AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.get_question_practice_analysis(timestamptz,timestamptz)')),false) AS ok
 UNION ALL SELECT 'get_question_practice_admin_statistics' AS name,coalesce((SELECT md5(prosrc)='bf9239b2c043abb5505b2b4c4ec6f2da' AND prosecdef=true AND proconfig=ARRAY['search_path=public, extensions'] FROM pg_proc WHERE oid=to_regprocedure('public.get_question_practice_admin_statistics(uuid,uuid,timestamptz,timestamptz)')),false) AS ok
 UNION ALL SELECT 'submit_question_practice_v2_privileges',has_function_privilege('authenticated','public.submit_question_practice_v2(uuid,uuid,uuid,integer,jsonb,boolean)','EXECUTE') AND NOT has_function_privilege('anon','public.submit_question_practice_v2(uuid,uuid,uuid,integer,jsonb,boolean)','EXECUTE')
 UNION ALL SELECT 'get_question_practice_analysis_privileges',has_function_privilege('authenticated','public.get_question_practice_analysis(timestamptz,timestamptz)','EXECUTE') AND NOT has_function_privilege('anon','public.get_question_practice_analysis(timestamptz,timestamptz)','EXECUTE')
 UNION ALL SELECT 'get_question_practice_admin_statistics_privileges',has_function_privilege('authenticated','public.get_question_practice_admin_statistics(uuid,uuid,timestamptz,timestamptz)','EXECUTE') AND NOT has_function_privilege('anon','public.get_question_practice_admin_statistics(uuid,uuid,timestamptz,timestamptz)','EXECUTE')
 UNION ALL SELECT 'question_practice_expected_seconds_private',NOT has_function_privilege('authenticated','public.question_practice_expected_seconds(public.question_difficulty)','EXECUTE') AND NOT has_function_privilege('anon','public.question_practice_expected_seconds(public.question_difficulty)','EXECUTE')
 UNION ALL SELECT 'question_practice_target_private',NOT has_function_privilege('authenticated','public.question_practice_target(bigint,bigint)','EXECUTE') AND NOT has_function_privilege('anon','public.question_practice_target(bigint,bigint)','EXECUTE')
 UNION ALL SELECT 'question_practice_signals_private',NOT has_function_privilege('authenticated','public.question_practice_signals()','EXECUTE') AND NOT has_function_privilege('anon','public.question_practice_signals()','EXECUTE')
 UNION ALL SELECT 'question_practice_snapshot_private',NOT has_function_privilege('authenticated','public.question_practice_snapshot(uuid)','EXECUTE') AND NOT has_function_privilege('anon','public.question_practice_snapshot(uuid)','EXECUTE')
 UNION ALL SELECT 'attempts_read_only',NOT has_table_privilege('authenticated','public.question_practice_attempts','INSERT,UPDATE,DELETE')
 UNION ALL SELECT 'sessions_read_only',NOT has_table_privilege('authenticated','public.question_practice_sessions','INSERT,UPDATE,DELETE')
 UNION ALL SELECT 'telemetry_columns',(SELECT count(*)=2 FROM information_schema.columns WHERE table_schema='public' AND table_name='question_practice_attempts' AND column_name IN ('selection_trajectory','timing_complete'))
) SELECT jsonb_build_object('all_checks_pass',bool_and(ok),'checks',jsonb_agg(jsonb_build_object('name',name,'ok',ok) ORDER BY name)) AS adaptation_verification FROM checks;
